// ============================================================
// pms_7sefun v6 video 脚本（由 build_v6.js 读入并内嵌进 JSON）
// 链路（三跳 meta + 终值）——与 probe_v6_inputs.js E 段逐字对齐：
//   hop0 parseVideo(vodplay 页): player_aaaa(from=lmm,encrypt=2) 解出 lmm85 跳转页
//     → meta1 GET lmm85 页（Referer=7sefun 播放页 context.url）
//   hop1 processLmm(lmm85 页): player_aaaa(from=dpmp4) 取 url 原文为 vid
//     → meta2 GET yun.92cj.com/mp4hls/?type=mp4&vid=enc(vid)&referer=enc(lmmUrl)（Referer=lmmUrl）
//   hop2 processYun(yun 页): 取 t/token/act/play，内嵌 AES-128-CBC 解 getc(token)
//     → meta3 POST yun.92cj.com/mp4hls/api.php（静态 Referer/Origin/XRW/CT + urlencoded body）
//   hop3 processApi(api.php JSON): 取 data.url 真直链（referer:never，无 Referer 可播）
// 跨 hop 传值用引擎共享全局（同一引擎实例单次评估，顶层函数赋值的全局存活于后续 hop）。
// 全部纯同步（真机 JS 引擎不支持异步调用）；HTTP 只经 __meta 协议由 Dart 预取。
// ============================================================

// ---- 宽松 base64 解码（v5 原实现，改名避开引擎 prelude 的 atob）----
function _sfAtob(s){var k='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';var o='';s=String(s).replace(/[^A-Za-z0-9+\/=]/g,'').replace(/=+$/,'');for(var i=0;i<s.length;i+=4){var a=k.indexOf(s.charAt(i)),b=k.indexOf(s.charAt(i+1)),c=i+2<s.length?k.indexOf(s.charAt(i+2)):-1,d=i+3<s.length?k.indexOf(s.charAt(i+3)):-1;if(c<0)c=0;if(d<0)d=0;o+=String.fromCharCode((a<<2)|(b>>4));if(i+2<s.length)o+=String.fromCharCode(((b&15)<<4)|(c>>2));if(i+3<s.length)o+=String.fromCharCode(((c&3)<<6)|d);}return o;}

// ---- AES-128-CBC 解密（表生成式，与 .tmp_pua_probe/aes_test.js ALL PASS 版逐字一致）----
function _aesTables() {
  if (_aesTables.S) return _aesTables;
  var S = new Array(256), SI = new Array(256), exp = new Array(256), log = new Array(256);
  var x = 1, i;
  for (i = 0; i < 255; i++) {
    exp[i] = x; log[x] = i;
    var t = (((x << 1) & 255) ^ ((x >> 7) ? 0x1b : 0));
    x = (t ^ x) & 255;
  }
  for (i = 0; i < 256; i++) {
    var inv = i === 0 ? 0 : exp[(255 - log[i]) % 255];
    var s = inv
      ^ ((inv << 1 | inv >>> 7) & 255)
      ^ ((inv << 2 | inv >>> 6) & 255)
      ^ ((inv << 3 | inv >>> 5) & 255)
      ^ ((inv << 4 | inv >>> 4) & 255)
      ^ 0x63;
    s &= 255;
    S[i] = s; SI[s] = i;
  }
  function mul(a, b) { if (a === 0 || b === 0) return 0; return exp[(log[a] + log[b]) % 255]; }
  _aesTables.S = S; _aesTables.SI = SI; _aesTables.exp = exp; _aesTables.log = log; _aesTables.mul = mul;
  return _aesTables;
}

function _hexB(h) { var o = []; for (var i = 0; i < h.length; i += 2) o.push(parseInt(h.substr(i, 2), 16)); return o; }

function _keyExpand(keyHex) {
  var T = _aesTables(), k = _hexB(keyHex), w = [], i;
  for (i = 0; i < 4; i++) w[i] = ((k[4 * i] << 24) | (k[4 * i + 1] << 16) | (k[4 * i + 2] << 8) | k[4 * i + 3]) >>> 0;
  var rc = 1;
  for (i = 4; i < 44; i++) {
    var t = w[i - 1];
    if (i % 4 === 0) {
      t = ((t << 8) | (t >>> 24)) >>> 0;
      t = (((T.S[(t >>> 24) & 255] << 24) | (T.S[(t >>> 16) & 255] << 16) | (T.S[(t >>> 8) & 255] << 8) | T.S[t & 255])) >>> 0;
      t = (t ^ (rc << 24)) >>> 0;
      rc = ((rc << 1) ^ ((rc >> 7) ? 0x1b : 0)) & 255;
    }
    w[i] = (w[i - 4] ^ t) >>> 0;
  }
  return w;
}

function _decBlock(ct, w) {
  var T = _aesTables(), s = ct.slice(), r, i;
  function ark(rd) {
    for (i = 0; i < 4; i++) {
      var wd = w[rd * 4 + i];
      s[4 * i] ^= (wd >>> 24) & 255; s[4 * i + 1] ^= (wd >>> 16) & 255;
      s[4 * i + 2] ^= (wd >>> 8) & 255; s[4 * i + 3] ^= wd & 255;
    }
  }
  function invShift() {
    var o = s.slice();
    for (var rr = 1; rr < 4; rr++) for (var c = 0; c < 4; c++) s[4 * c + rr] = o[4 * ((c - rr + 4) % 4) + rr];
  }
  function invSub() { for (i = 0; i < 16; i++) s[i] = T.SI[s[i]]; }
  function invMix() {
    for (var c = 0; c < 4; c++) {
      var a0 = s[4 * c], a1 = s[4 * c + 1], a2 = s[4 * c + 2], a3 = s[4 * c + 3];
      s[4 * c] = (T.mul(a0, 14) ^ T.mul(a1, 11) ^ T.mul(a2, 13) ^ T.mul(a3, 9)) & 255;
      s[4 * c + 1] = (T.mul(a0, 9) ^ T.mul(a1, 14) ^ T.mul(a2, 11) ^ T.mul(a3, 13)) & 255;
      s[4 * c + 2] = (T.mul(a0, 13) ^ T.mul(a1, 9) ^ T.mul(a2, 14) ^ T.mul(a3, 11)) & 255;
      s[4 * c + 3] = (T.mul(a0, 11) ^ T.mul(a1, 13) ^ T.mul(a2, 9) ^ T.mul(a3, 14)) & 255;
    }
  }
  ark(10);
  for (r = 9; r >= 1; r--) { invShift(); invSub(); ark(r); invMix(); }
  invShift(); invSub(); ark(0);
  return s;
}

function _aesCbcDecB64(b64, keyHex, ivHex) {
  var B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  function b64d(s) {
    s = String(s).replace(/[^A-Za-z0-9+\/=]/g, '').replace(/=+$/, '');
    var out = [], i;
    for (i = 0; i < s.length; i += 4) {
      var a = B64.indexOf(s.charAt(i)), b = B64.indexOf(s.charAt(i + 1));
      var c = i + 2 < s.length ? B64.indexOf(s.charAt(i + 2)) : -1;
      var d = i + 3 < s.length ? B64.indexOf(s.charAt(i + 3)) : -1;
      if (c < 0) c = 0; if (d < 0) d = 0;
      out.push((a << 2) | (b >> 4));
      if (i + 2 < s.length) out.push(((b & 15) << 4) | (c >> 2));
      if (i + 3 < s.length) out.push(((c & 3) << 6) | d);
    }
    return out;
  }
  var data = b64d(b64), w = _keyExpand(keyHex), prev = _hexB(ivHex), out = [];
  for (var off = 0; off + 16 <= data.length; off += 16) {
    var blk = data.slice(off, off + 16);
    var dec = _decBlock(blk, w);
    for (var i = 0; i < 16; i++) out.push(dec[i] ^ prev[i]);
    prev = blk;
  }
  var n = out.length ? out[out.length - 1] : 0;
  if (n >= 1 && n <= 16) out.length -= n;
  var s = '';
  for (var j = 0; j < out.length; j++) s += String.fromCharCode(out[j]);
  return s;
}

// ---- getc(token)：yun.92cj.com 云播页令牌解密（AES-128-CBC，固定 key/iv）----
var _GETC_KEY = '265f4d5026477a465375384d5f6a6b70';
var _GETC_IV = '347763794967682b23674b4476285243';
function _getc(token) {
  try {
    var s = _aesCbcDecB64(token, _GETC_KEY, _GETC_IV);
    return /^[0-9a-fA-F]{32}$/.test(s) ? s : '';
  } catch (e) { return ''; }
}

// ---- player_aaaa {...} 提取（括号配平 + JSON 失败回退正则，探针逐字）----
function _sfPlayerCfg(html) {
  try {
    var i = html.indexOf('player_aaaa');
    if (i < 0) return null;
    var k = html.indexOf('{', i);
    if (k < 0) return null;
    var depth = 0, end = -1;
    for (var j = k; j < html.length; j++) { var c = html.charAt(j); if (c == '{') depth++; else if (c == '}') { depth--; if (depth == 0) { end = j + 1; break; } } }
    if (end < 0) return null;
    var txt = html.substring(k, end);
    var cfg = null;
    try { cfg = JSON.parse(txt); } catch (e) { }
    if (!cfg) { try { cfg = JSON.parse(txt.replace(/'/g, '"').replace(/,\s*}/g, '}').replace(/\{\s*,/g, '{')); } catch (e) { } }
    if (cfg && typeof cfg === 'object') return { from: String(cfg.from || ''), encrypt: cfg.encrypt || 0, url: String(cfg.url || ''), urlNext: String(cfg.url_next || '') };
    function rg(re) { var m = re.exec(txt); return m ? m[1] : ''; }
    var f = rg(/from\s*:\s*['"]([^'"]*)['"]/), en = rg(/encrypt\s*:\s*['"]?(\d+)/), uu = rg(/[{,\s]url\s*:\s*['"]([^"']*)['"]/), un = rg(/url_next\s*:\s*['"]([^'"]*)['"]/);
    if (uu) return { from: f, encrypt: parseInt(en || '0', 10) || 0, url: uu, urlNext: un };
    return null;
  } catch (e) { return null; }
}

// ---- player_aaaa url 按 encrypt 解码（v5 语义：2=base64(+hex/percent)，1=percent）----
function _sfDecUrl(u, enc) {
  var s = String(u || '');
  if (enc == 2) {
    s = _sfAtob(s);
    if (/^[0-9a-fA-F]+$/.test(s)) { var t = ''; for (var q = 0; q < s.length; q += 2) t += String.fromCharCode(parseInt(s.substr(q, 2), 16)); s = t; }
    try { s = decodeURIComponent(s); } catch (e) { }
    try { s = decodeURIComponent(s); } catch (e) { }
  } else if (enc == 1) {
    try { s = decodeURIComponent(s); } catch (e) { }
  }
  return s;
}

var _SF_MEDIA_RE = /\.(mp4|m3u8|mkv|avi|flv|mov|webm|ts)(\?|#|$)/i;

// ---- hop0 入口（override.function=parseVideo）：vodplay 页 → 直链 或 meta1(lmm85) ----
function parseVideo(html) {
  try {
    html = String(html || '');
    // 播放页自身地址（video 路由 vars={'url': episodeUrl} → context.url 为 JSON 字符串；
    // 剧集 url 为相对路径 /vodplay/...，Referer 必须绝对化否则是非法头）
    var pageUrl = '';
    try { pageUrl = JSON.parse(context.url) || ''; } catch (e) { pageUrl = ''; }
    if (!pageUrl) { try { pageUrl = String(context.url || ''); } catch (e2) { pageUrl = ''; } }
    if (pageUrl && pageUrl.indexOf('http') !== 0) {
      pageUrl = 'https://www.7sefun.top' + (pageUrl.charAt(0) === '/' ? '' : '/') + pageUrl;
    }
    if (!pageUrl) pageUrl = 'https://www.7sefun.top/';
    var cfg = _sfPlayerCfg(html);
    if (cfg) {
      var u = _sfDecUrl(cfg.url, cfg.encrypt);
      if (u && u.indexOf('http') === 0) {
        if (_SF_MEDIA_RE.test(u)) return { url: u };
        __sfLmmUrl = u; // lmm85 页地址，hop1/hop2 引用
        return {
          __meta: true, __fetchUrl: u, __fetchResponseType: 'text', __processor: 'processLmm',
          __fetchHeaders: { 'Referer': pageUrl || 'https://www.7sefun.top/' }
        };
      }
    }
    var p = html.indexOf('.m3u8');
    if (p >= 0) {
      var a = html.lastIndexOf('http', p);
      if (a >= 0) {
        var e = p + 5;
        while (e < html.length) { var cc = html.charCodeAt(e); if (cc === 34 || cc === 39 || cc === 60 || cc === 62 || cc === 32 || cc === 10 || cc === 13 || cc === 9) break; e++; }
        var mu = html.substring(a, e);
        if (mu.indexOf('http') === 0) return { url: mu };
      }
    }
    return '';
  } catch (e) { return ''; }
}

// ---- hop1：lmm85 跳转页 → meta2(yun 云播页)（探针 E 段：无媒体捷径，恒走 yun）----
function processLmm(html) {
  try {
    var cfg = _sfPlayerCfg(String(html || ''));
    if (!cfg) return '';
    var u = _sfDecUrl(cfg.url, cfg.encrypt);
    if (!u || u.indexOf('http') !== 0) return '';
    var lmmUrl = (typeof __sfLmmUrl === 'string' && __sfLmmUrl) ? __sfLmmUrl : u;
    __sfVid = u; // POST body 的 vid = lmm 页 player_aaaa.url 原文（探针 :163/:172 真值）
    var yun = 'https://yun.92cj.com/mp4hls/?type=mp4&vid=' + encodeURIComponent(u) + '&referer=' + encodeURIComponent(lmmUrl);
    return {
      __meta: true, __fetchUrl: yun, __fetchResponseType: 'text', __processor: 'processYun',
      __fetchHeaders: { 'Referer': lmmUrl }
    };
  } catch (e) { return ''; }
}

// ---- hop2：yun 云播页 → 解 getc(token) → meta3(POST api.php) ----
function processYun(html) {
  try {
    html = String(html || '');
    var rg = function (re) { var m = re.exec(html); return m ? m[1] : ''; };
    var token = rg(/var\s+token\s*=\s*["']([^"']+)["']/);
    if (!token) return '';
    var dt = _getc(token);
    if (!dt) return '';
    var t = rg(/var\s+t\s*=\s*["']([^"']+)["']/);
    var vid = (typeof __sfVid === 'string' && __sfVid) ? __sfVid : rg(/var\s+vid\s*=\s*["']([^"']+)["']/);
    var act = rg(/var\s+act\s*=\s*["']([^"']+)["']/);
    var play = rg(/var\s+play\s*=\s*["']([^"']+)["']/);
    var body = 'vid=' + encodeURIComponent(vid) + '&t=' + encodeURIComponent(t) + '&token=' + encodeURIComponent(dt) + '&act=' + encodeURIComponent(act || '0') + '&play=' + encodeURIComponent(play || '1');
    return {
      __meta: true,
      __fetchUrl: 'https://yun.92cj.com/mp4hls/api.php',
      __fetchMethod: 'post',
      __fetchBody: body,
      __fetchResponseType: 'json',
      __processor: 'processApi',
      __fetchHeaders: {
        'Referer': 'https://yun.92cj.com/mp4hls/',
        'Origin': 'https://yun.92cj.com',
        'X-Requested-With': 'XMLHttpRequest',
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'
      }
    };
  } catch (e) { return ''; }
}

// ---- hop3（终值）：api.php 响应 → 真直链 ----
function processApi(data) {
  try {
    var u = '';
    if (data) {
      if (typeof data === 'string') {
        try { var j = JSON.parse(data); if (j && j.url) u = String(j.url); }
        catch (e) { var m = /"url"\s*:\s*"([^"]+)"/.exec(data); if (m) u = m[1]; }
      } else if (typeof data === 'object' && data.url) {
        u = String(data.url);
      }
    }
    u = u.replace(/\\\//g, '/');
    if (u && u.indexOf('http') === 0) return { url: u };
    return '';
  } catch (e) { return ''; }
}
